BEGIN;
CREATE SCHEMA bench_jsonb;
CREATE TABLE bench_jsonb.inputs (fixture text PRIMARY KEY, checksum text NOT NULL, payload jsonb NOT NULL);
CREATE TABLE bench_jsonb.generations (id text PRIMARY KEY, fixture text NOT NULL REFERENCES bench_jsonb.inputs, metadata jsonb NOT NULL);
CREATE TABLE bench_jsonb.releases (id text PRIMARY KEY, manifest jsonb NOT NULL);
CREATE TABLE bench_jsonb.days (generation text NOT NULL REFERENCES bench_jsonb.generations, date date NOT NULL, checksum text NOT NULL, sample_count int NOT NULL, payload jsonb NOT NULL, PRIMARY KEY(generation,date));
CREATE SCHEMA bench_arrays;
CREATE TABLE bench_arrays.inputs (fixture text PRIMARY KEY, checksum text NOT NULL, payload jsonb NOT NULL);
CREATE TABLE bench_arrays.generations (id text PRIMARY KEY, fixture text NOT NULL REFERENCES bench_arrays.inputs, metadata jsonb NOT NULL);
CREATE TABLE bench_arrays.releases (id text PRIMARY KEY, manifest jsonb NOT NULL);
CREATE TABLE bench_arrays.days (generation text NOT NULL REFERENCES bench_arrays.generations, date date NOT NULL, checksum text NOT NULL, sample_count int NOT NULL, offsets integer[] NOT NULL, exposure double precision[] NOT NULL, CHECK(cardinality(offsets)=cardinality(exposure)), PRIMARY KEY(generation,date));
CREATE SCHEMA bench_bytes;
CREATE TABLE bench_bytes.inputs (fixture text PRIMARY KEY, checksum text NOT NULL, payload jsonb NOT NULL);
CREATE TABLE bench_bytes.generations (id text PRIMARY KEY, fixture text NOT NULL REFERENCES bench_bytes.inputs, metadata jsonb NOT NULL);
CREATE TABLE bench_bytes.releases (id text PRIMARY KEY, manifest jsonb NOT NULL);
CREATE TABLE bench_bytes.days (generation text NOT NULL REFERENCES bench_bytes.generations, date date NOT NULL, checksum text NOT NULL, sample_count int NOT NULL, payload bytea NOT NULL, PRIMARY KEY(generation,date));
COMMIT;
ANALYZE;
